'use strict';
/* ============================================================
   The wider bestiary: the classic creatures of the first
   Monster Manual, set down in the same form as the rest of
   the game's monsters (Hit Dice, armor class, THAC0, morale).
   None of them is placed in an adventure here; they are the
   stock that adventures and encounter tables draw on.
   ============================================================ */

/* THAC0 and experience follow from Hit Dice by the standard tables unless an entry gives its own.
   Hit Dice are written as elsewhere: 4.3 is 4+3, 0.9 is 1-1, 0.5 is half a die. */
function monHdParts(hd) { return { n: Math.floor(hd), plus: Math.round((hd % 1) * 10) }; }
function monThac0(hd) {
  if (hd < 1) return 20;
  const { n, plus } = monHdParts(hd), e = n + (plus >= 3 ? 1 : 0);
  return Math.max(1, 21 - 2 * Math.ceil(e / 2));
}
const MON_XP = [7, 15, 35, 65, 120, 175, 270, 420, 650, 975, 1400, 2000, 2000];
/* bonus: extra Hit Dice of worth for special attacks and defences */
function monXP(hd, bonus) {
  const { n, plus } = monHdParts(hd);
  const e = (hd <= 0.5 ? 0 : hd < 1 ? 1 : n + (plus > 0 ? 1 : 0)) + (bonus || 0);
  return e >= 13 ? 3000 + 1000 * (e - 13) : MON_XP[e];
}
function monHp(hd) {
  if (hd <= 0.5) return '1d4';
  if (hd < 1) return '1d8-1';
  const { n, plus } = monHdParts(hd);
  return n + 'd8' + (plus ? '+' + plus : '');
}
/* mon(name, Hit Dice, armor class, move, attacks, size, morale, tags, everything else) */
function mon(name, hd, ac, mv, atk, size, ml, tags, o) {
  o = o || {};
  const m = Object.assign({ name, hd, hp: monHp(hd), ac, mv, thac0: monThac0(hd), atk, size, ml, xp: monXP(hd, o.xb), gold: '0', tags }, o);
  delete m.xb;
  return m;
}

/* breath weapons and gazes used by more than one creature */
const BREATH = {
  fire: (dmg, o) => Object.assign({ dmg, range: 6, r: 1.5, every: 3, uses: 3, text: 'breathes a cone of fire', color: '#ff6a1a' }, o),
  cold: (dmg, o) => Object.assign({ dmg, range: 5, r: 1.5, every: 3, uses: 3, text: 'breathes a cone of killing frost', color: '#bfe6ff' }, o),
  acid: (dmg, o) => Object.assign({ dmg, range: 6, r: 1, every: 3, uses: 3, text: 'spits a stream of acid', color: '#9be36a' }, o),
  lightning: (dmg, o) => Object.assign({ dmg, range: 8, r: 1, every: 3, uses: 3, text: 'breathes a stroke of lightning', color: '#bfe6ff' }, o),
  gas: (dmg, o) => Object.assign({ dmg, range: 5, r: 2, every: 3, uses: 3, save: 0, text: 'breathes a cloud of poison gas', color: '#8fae3a' }, o),
};
